-- Apply division migration first. One-time audited master additions; does not modify contact history.
BEGIN;
LOCK TABLE public.recruiting_universities IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM public.recruiting_universities WHERE id BETWEEN 107 AND 130) THEN RAISE EXCEPTION 'Reserved school IDs are occupied; re-audit before writing'; END IF;
END $$;
